using namespace std;



typedef long long ll;



ll count_rooms_lesseq_than(ll newRoomNo)

{

	int t[10], d;

	for (d = 0; newRoomNo; ++d, newRoomNo /= 10)

		t[d] = newRoomNo % 10;

	for (int i = d-1; i > 0; --i)

	{

		if (t[i] == 4 || t[i] == 6)

		{

			--t[i];

			for (int j = 0; j < i; ++j)

				t[j] = 9;

			break;

		}

	}



	ll res = 0;

	for (int i = 0; i < d; ++i)

	{

		ll a = 1;

		for (int j = 0; j < i; ++j)

			a *= 8;

		res += (t[i] - (t[i] >= 6 ? 2 : t[i] >= 4 ? 1 : 0)) * a;

	}

	return res;

}

int main()

{

	int n;

	while (scanf("%d", &n), n)

	{

		ll l, u;

		l = 1;

		u = n * 10LL;

		while (l < u)

		{

			ll m = (l + u) / 2;

			ll t = count_rooms_lesseq_than(m);

			if (t < n)

				l = m + 1;

			else

				u = m;

		}

		printf("%lld
", l);

	}



	return 0;

}

#include<iostream>

using namespace std;



typedef long long ll;



ll gcd(ll a,ll b){

  return (!b)?a:gcd(b,a%b);

}



int main(){

  int n;

  ll d[10],v[10],t[10];



  for(;;){

    cin >> n;

    if(!n)break;



    for(int i=0;i<n;i++)cin >> d[i] >> v[i];

    t[0] = 1;

    for(int i=1;i<n;i++){

      t[i] = t[i-1]*d[i-1]*v[i];

      for(int j=0;j<i;j++)t[j] *= d[i]*v[i-1];

      ll T = t[0];

      for(int j=1;j<=i;j++)T = gcd(T,t[j]);

      for(int j=0;j<=i;j++)t[j]/=T;

    }



    for(int i=0;i<n;i++)cout << t[i] << endl;

  }

}

#include <iostream>

#include <algorithm>

using namespace std;



long long d[10],v[10];



void compute(int n){

    for(int i = 2 ; i <= min(d[n],v[n]) ; i++){

        if(d[n]%i==0||v[n]%i==0){

            while(d[n]%i==0&&v[n]%i==0){

                d[n] /= i;

                v[n] /= i;

            }

        }

    }

}



int main(){

    int n;



    while(cin >>n,n){

        long long a,b;

        for(int i = 0 ; i < n ; i++){

            cin >> d[i] >> v[i];

            compute(i);

        }



        a = (d[0]*d[1])/__gcd(d[0],d[1]);

        b = __gcd(v[0],v[1]);



        for(int i = 2 ; i < n ; i++){

            a = (a*d[i])/__gcd(a,d[i]);

            b = __gcd(b,v[i]);

        }



        for(int i = 0 ; i < n ; i++){

            cout << a*v[i]/(b*d[i]) << endl;

        }

    }



    return 0;

}
